import { Page, Locator } from '@playwright/test';

export class InventoryPage {
  readonly page: Page;
  readonly title: Locator;
  readonly logoutButton: Locator;
  readonly openMenuButton: Locator;
  readonly cartBadge: Locator;
  readonly cartLink: Locator;
  readonly sortDropdown: Locator;
  readonly itemNames: Locator;
  readonly itemPrices: Locator;

  constructor(page: Page) {
    this.page = page;
    this.title = page.locator('[data-test="title"]');
    this.logoutButton = page.locator('[data-test="logout-sidebar-link"]');
    this.openMenuButton = page.getByRole('button', { name: 'Open Menu' });

    this.cartBadge = page.locator('[data-test="shopping-cart-badge"]');
    this.cartLink = page.locator('[data-test="shopping-cart-link"]');

    this.sortDropdown = page.locator('[data-test="product-sort-container"]');

    this.itemNames = page.locator('[data-test="inventory-item-name"]');
    this.itemPrices = page.locator('[data-test="inventory-item-price"]');
  }

  async logout() {
    await this.logoutButton.click();
  }

  async openMenu() {
    await this.openMenuButton.click();
  }


  private productContainer(productName: string): Locator {
    return this.page.locator('.inventory_item').filter({ hasText: productName });
  }

  getProductButton(productName: string): Locator {
    return this.productContainer(productName).getByRole('button', {
      name: /Add to cart|Remove/,
    });
  }

  async addProductToCart(productName: string) {
    await this.productContainer(productName)
      .getByRole('button', { name: 'Add to cart' })
      .click();
  }

  async removeProductFromCart(productName: string) {
    await this.productContainer(productName)
      .getByRole('button', { name: 'Remove' })
      .click();
  }

  async sortBy(optionValue: string) {
    await this.sortDropdown.selectOption(optionValue);
  }

  async getAllPricesAsNumbers(): Promise<number[]> {
    const texts = await this.itemPrices.allTextContents();
    return texts.map((text) => parseFloat(text.replace('$', '')));
  }

  async getAllProductNames(): Promise<string[]> {
    return this.itemNames.allTextContents();
  }
}import { Page, Locator } from '@playwright/test';

export class LoginPage {
  readonly page: Page;
  readonly usernameInput: Locator;
  readonly passwordInput: Locator;
  readonly loginButton: Locator;
  readonly errorMessage: Locator;

  constructor(page: Page) {
    this.page = page;
    this.usernameInput = page.locator('[data-test="username"]');
    this.passwordInput = page.locator('[data-test="password"]');
    this.loginButton = page.locator('[data-test="login-button"]');
    this.errorMessage = page.locator('[data-test="error"]');
  }

  async goto() {
    await this.page.goto('/');
  }

  async login(username: string, password: string) {
    await this.usernameInput.fill(username);
    await this.passwordInput.fill(password);
    await this.loginButton.click();
  }
}
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';
import { CartPage } from '../pages/CartPage';
import { InventoryPage } from '../pages/InventoryPage';
import testData from '../fixtures/testData.json';


// --------------- Válidos (Caminho Feliz)

test.describe('Domínio de Catálogo e Carrinho', () => {
  test.beforeEach(async ({ page }) => {
    // Condição: usuário na rota "/inventory.html"
    const loginPage = new LoginPage(page);
    await loginPage.goto();
    await loginPage.login(
      testData.users.standard.username,
      testData.users.standard.password
    );
    await expect(page).toHaveURL(/.*inventory\.html/);
  });

  test('TC-004: Adicionar um único item ao carrinho a partir da vitrine', async ({ page }) => {
    const inventoryPage = new InventoryPage(page);
    const productName = testData.products.backpack;

    // Ação: clicar no botão "Add to cart" do card do produto na vitrine
    await inventoryPage.addProductToCart(productName);

    // Resultado esperado: o botão muda para "Remove" e o ícone do carrinho exibe o número 1
    await expect(inventoryPage.getProductButton(productName)).toHaveText('Remove');
    await expect(inventoryPage.cartBadge).toHaveText('1');
  });

  test('TC-005: Adicionar múltiplos itens diferentes ao carrinho', async ({ page }) => {
    const inventoryPage = new InventoryPage(page);
    const products = [
      testData.products.backpack,
      testData.products.bikeLight,
      testData.products.boltTShirt,
    ];

    // Ação: Adicionar cada produto da lista ao carrinho
    for (const productName of products) {
      await inventoryPage.addProductToCart(productName);
    }

    // Resultado esperado: os botões mudam para "Remove" e o ícone do carrinho exibe o número 3
    for (const productName of products) {
      await expect(inventoryPage.getProductButton(productName)).toHaveText('Remove');
    }
    await expect(inventoryPage.cartBadge).toHaveText(String(products.length));
  });

  test('TC-006: Remover um item que já estava no carrinho clicando no botão da própria vitrine', async ({ page }) => {
    const inventoryPage = new InventoryPage(page);
    const productName = testData.products.backpack;

    // Condição: item já adicionado
    await inventoryPage.addProductToCart(productName);
    await expect(inventoryPage.cartBadge).toBeVisible();

    await expect(loginPage.loginButton).toBeVisible();
  });
  test('TC-011: Tentativa de login com senha incorreta', async ({ page }) => {
    const loginPage = new LoginPage(page);

    // Pré-condição: Usuário na tela de login
    await loginPage.goto();

    // Ação: Preencher usuário e senha inválidos e clicar em Login
    await loginPage.login(
      testData.users.invalidCredentials.username,
      testData.users.invalidCredentials.password
    );

    // Resultado esperado: Exibe mensagem "Epic sadface: Username and password do not match any user in this service"; permanece na tela de login (`/`)
    await expect(page).toHaveURL(/.*/);
    await expect(loginPage.errorMessage).toBeVisible();
    await expect(loginPage.errorMessage).toHaveText(
      testData.errorMessages.invalidCredentials
    );
  });
  test('TC-012: Tentativa de login com usuário bloqueado', async ({ page }) => {
    const loginPage = new LoginPage(page);

    // Pré-condição: Usuário na tela de login
    await loginPage.goto();

    // Ação: Preencher usuário e senha de um usuário bloqueado e clicar em Login
    await loginPage.login(
      testData.users.lockedOut.username,
      testData.users.lockedOut.password
    );

    // Resultado esperado: Exibe mensagem "Epic sadface: Sorry, this user has been locked out."; permanece na tela de login (`/`)
    await expect(page).toHaveURL(/.*/);
    await expect(loginPage.errorMessage).toBeVisible();
    await expect(loginPage.errorMessage).toHaveText(
      testData.errorMessages.lockedOut
    );
  });
    test('TC-013: Submissão de login com campos vazios', async ({ page }) => {
    const loginPage = new LoginPage(page);

    // Pré-condição: Usuário na tela de login
    await loginPage.goto();

    // Ação: Submeter o formulário com campos vazios e clicar em Login
    await loginPage.login(
      testData.users.empty.username,
      testData.users.empty.password
    );

    // Resultado esperado: Exibe mensagem "Epic sadface: Username is required."; permanece na tela de login (`/`)
    await expect(page).toHaveURL(/.*/);
    await expect(loginPage.errorMessage).toBeVisible();
    await expect(loginPage.errorMessage).toHaveText(
      testData.errorMessages.usernameRequired
    );
  });
  test('TC-014: Tentativa de retroceder navegador após logout', async ({ page }) => {
    const loginPage = new LoginPage(page);
    const inventoryPage = new InventoryPage(page);

    // Pré-condição: Usuário recém deslogado na tela de login
    await loginPage.goto();
    await loginPage.login(
      testData.users.standard.username,
      testData.users.standard.password
    );
    await inventoryPage.openMenu();
    await inventoryPage.logout();

    // Ação: Retroceder o navegador"

    await page.goBack();

    // Resultado esperado:  Exibe mensagem "Epic sadface: Username is required."; permanece na tela de login (`/`)
    await expect(page).toHaveURL(/.*/);
    await expect(loginPage.errorMessage).toBeVisible();
    await expect(loginPage.errorMessage).toHaveText(
      testData.errorMessages.unauthorizedInventory
    );
  });
});
