'use strict';
const { execFileSync } = require('child_process');
const fs = require('fs');

const DB = process.env.HOME + '/.local/share/opencode/opencode.db';
const SESSION = 'ses_e62ce1243ffehUBPioGsJzNz8C';

const raw = execFileSync('sqlite3', [DB,
  `select seq, type, time_created, data from session_message where session_id='${SESSION}' and type in ('user','assistant') order by seq;`
], { encoding: 'utf8', maxBuffer: 200 * 1024 * 1024 });

const rows = [];
for (const line of raw.split('\n')) {
  if (!line.trim()) continue;
  const [seq, type, ts, ...rest] = line.split('|');
  rows.push({ seq: Number(seq), type, ts: Number(ts), data: JSON.parse(rest.join('|')) });
}

const fmtTime = (ms) => new Date(ms).toLocaleString('pt-BR', {
  timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit',
});

function summarizeTool(name, input) {
  const key = ['command', 'path', 'pattern', 'url', 'filePath', 'description']
    .find((k) => input && typeof input[k] === 'string');
  let detail = key ? input[key] : '';
  detail = String(detail).replace(/\s+/g, ' ').trim();
  if (detail.length > 110) detail = detail.slice(0, 110) + '…';
  return detail ? `\`${name}\` — ${detail}` : `\`${name}\``;
}

// Agrupa mensagens do agente entre mensagens do usuário
const turns = [];
for (const row of rows) {
  if (row.type === 'user') {
    turns.push({ user: row, agent: [] });
  } else {
    if (turns.length === 0) turns.push({ user: null, agent: [] });
    turns[turns.length - 1].agent.push(row);
  }
}

const out = [];
out.push('# Transcrição da Sessão de IA — Projeto S07 / NP2');
out.push('');
out.push('**Disciplina:** S07 — Gerência de Configuração e Evolução de Software  ');
out.push('**Entrega:** NP2 — Aplicando DevOps na prática  ');
out.push('**Repositório:** https://github.com/generoso28/s07--qualidade-gerencia  ');
out.push('**Data da sessão:** 02/11/2026');
out.push('');
out.push('| Item | Valor |');
out.push('| --- | --- |');
out.push('| Ambiente | OpenCode (agente de código em terminal) |');
out.push('| Modelo | DeepSeek V4.1 Flash Free |');
out.push(`| Identificador da sessão | \`${SESSION}\` |`);
out.push(`| Turnos do usuário | ${turns.filter((t) => t.user).length} |`);
out.push('| Registro | Gerado a partir do banco de sessões do OpenCode |');
out.push('');
out.push('---');
out.push('');
out.push('## Como ler este documento');
out.push('');
out.push('| Elemento | Tratamento |');
out.push('| --- | --- |');
out.push('| Mensagens do usuário | **Transcritas literalmente** |');
out.push('| Respostas em texto do agente | **Transcritas literalmente** |');
out.push('| Chamadas de ferramenta | Resumidas em uma linha (nome + primeiro argumento) |');
out.push('| Saídas de ferramenta | Omitidas para legibilidade; permanecem no registro da sessão |');
out.push('| Raciocínio interno do modelo | Omitido (não faz parte da conversa) |');
out.push('');
out.push('Os comandos executados e seus resultados estão documentados em `docs/uso-de-ia.md`, seção 7.');
out.push('');
out.push('---');
out.push('');

let n = 0;
for (const turn of turns) {
  if (!turn.user) continue;
  n += 1;
  out.push(`## Turno ${n} — ${fmtTime(turn.user.ts)}`);
  out.push('');
  out.push('### 👤 Usuário');
  out.push('');
  const userText = String(turn.user.data.text ?? '').trim();
  for (const line of userText.split('\n')) out.push(line ? `> ${line}` : '>');
  out.push('');

  const blocks = [];
  for (const msg of turn.agent) {
    for (const c of msg.data.content ?? []) {
      if (c.type === 'text') {
        const t = String(c.text ?? '').trim();
        if (t) blocks.push({ kind: 'text', text: t });
      } else if (c.type === 'tool') {
        blocks.push({ kind: 'tool', text: summarizeTool(c.name, c.state && c.state.input) });
      }
    }
  }

  out.push('### 🤖 Agente');
  out.push('');
  if (blocks.length === 0) {
    out.push('_(sem resposta registrada)_');
    out.push('');
  }
  let lastKind = null;
  for (const b of blocks) {
    if (b.kind === 'text') {
      out.push(b.text);
      out.push('');
    } else {
      out.push(`> 🔧 ${b.text}`);
      out.push('');
    }
    lastKind = b.kind;
  }
  out.push('---');
  out.push('');
}

fs.writeFileSync('/home/lucas/Code/s07--qualidade-gerencia/docs/transcricao-sessao-ia.md', out.join('\n'));
